coverage=dict(completedAt=now,reviewerId=e['reviewerId'],priorCompletePageInspectionPath=e['priorFullSourceInspectionEvidence'],priorCoverageChallengePath='audits/W08-L36-contracts-coverage-challenge.json',actualPagesInSource=39,currentCitationPagesReinspected=19,currentObjectsReviewed=11,boundedGapsClosed=closures,remainingNewBoundedGaps=[],legacyQualityConcerns=oldcoverage['legacyQualityConcerns'],sourceQualificationsRemain=True,releaseComplete=False,limitation='All 85 objects have matching existing or current accepted reviews; this does not erase two separately reported legacy quality concerns. The 39 older search objects are not represented as freshly nine-gate re-reviewed.',codeScope=c['codeScope']);write('audits/W08-L36-v2-contracts-coverage-challenge.json',coverage)
